98: function makeWheel(front, accentMat) {
99:   const radius = front ? 0.355 : 0.395;
100:   const width = front ? 0.34 : 0.46;
101:   const steer = new THREE.Group();
102:   const spin = new THREE.Group();
103:   steer.add(spin);
104: 
105:   const rubber = new THREE.MeshStandardMaterial({ color: 0x0c0d0f, roughness: 0.92, metalness: 0.05 });
106:   const rimMat = new THREE.MeshStandardMaterial({ color: 0x2c2f34, roughness: 0.35, metalness: 0.9 });
107:   const accent = new THREE.MeshStandardMaterial({ color: 0xff4d1f, emissive: 0x401005, emissiveIntensity: 0.5, roughness: 0.35, metalness: 0.3 });
108: 
109:   const tireGeo = new THREE.CylinderGeometry(radius, radius, width, 28, 1);
110:   tireGeo.rotateZ(Math.PI / 2);
111:   const tire = new THREE.Mesh(tireGeo, rubber);
112:   tire.castShadow = true;
113:   spin.add(tire);
114: 
115:   // sidewall rings
116:   for (const side of [-1, 1]) {
117:     const ring = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.79, 0.012, 6, 32), accent);
118:     ring.rotation.y = Math.PI / 2;
119:     ring.position.x = side * (width / 2 + 0.004);
120:     spin.add(ring);
121:   }
122: 
123:   // rim + spokes
124:   const rimGeo = new THREE.CylinderGeometry(radius * 0.6, radius * 0.6, width + 0.01, 24, 1);
125:   rimGeo.rotateZ(Math.PI / 2);
126:   const rim = new THREE.Mesh(rimGeo, rimMat);
127:   spin.add(rim);
128: 
129:   for (let k = 0; k < 5; k++) {
130:     const spoke = new THREE.Mesh(new THREE.BoxGeometry(width * 0.5, 0.045, radius * 1.24), rimMat);
131:     spoke.rotation.x = (k / 5) * Math.PI;
132:     spin.add(spoke);
133:   }
134:   const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, width + 0.08, 12), accentMat);
135:   hub.geometry.rotateZ(Math.PI / 2);
136:   spin.add(hub);
137: 
138:   return { steer, spin, radius, width };
139: }
