966: function autoDriveDemand(p, track) {
967:   const N = track.N;
968:   const base = Math.floor((((p.sNorm % 1) + 1) % 1) * N) % N;
969:   const speed = Math.max(0, p.vLong);
970:   const lookAhead = clamp(55 + speed * 1.55, 55, 190);
971:   const stride = Math.max(1, Math.round(5 / track.step));
972:   const maxSteps = Math.round(lookAhead / track.step);
973:   let target = AUTODRIVE.maxSpeed;
974: 
975:   // Scan the road ahead and find the fastest speed we can still brake down to
976:   // every upcoming corner from. This does the "when do I lift?" thinking.
977:   for (let d = 0; d <= maxSteps; d += stride) {
978:     const s = track.samples[(base + d) % N];
979:     const radius = Math.max(1 / Math.max(Math.abs(s.k), 1e-5), 24);
980:     const corner = Math.sqrt(AUTODRIVE.lateral * radius);
981:     const dist = d * track.step;
982:     target = Math.min(target, Math.sqrt(corner * corner + 2 * AUTODRIVE.brakeDecel * dist));
983:   }
984:   if (p.offroad) target = Math.min(target, AUTODRIVE.offroadMax);
985:   target = clamp(target, AUTODRIVE.minSpeed, AUTODRIVE.maxSpeed);
986: 
987:   const gap = target - speed;
988:   const throttle = clamp(AUTODRIVE.cruiseThrottle + gap * 0.55, 0, 1);
989:   const brake = speed > target + 0.8
990:     ? clamp((speed - target - 0.8) / 5, 0.12, 1)
991:     : 0;
992:   return { throttle, brake, target };
993: }
