1292:     const lateral = a.lateral + Math.sin(a.dist / 44 + a.phase) * 0.85;
1293:     const x = s.x + s.nx * lateral;
1294:     const z = s.z + s.nz * lateral;
1295:     const yaw = Math.atan2(s.tx, s.tz);
