import { createRequire } from 'node:module';
import { join } from 'node:path';

const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR
  || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1100, height: 700 } });
page.on('pageerror', (e) => console.log('PAGE ERROR:', e.message));
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE ERROR:', m.text()); });
await page.goto('http://127.0.0.1:3011/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.race && window.__apex.race.state === 'racing', null, { timeout: 60000 });

const result = await page.evaluate(async () => {
  const r = window.__apex.race;
  const p = r.player;
  const a = r.ai[0];
  // Park the other two AI cars far behind so only one car is in play.
  r.ai[1].dist = -400;
  r.ai[2].dist = -420;

  const yaw = a.model.root.rotation.y;
  const fx = Math.sin(yaw), fz = Math.cos(yaw);
  // Place the player right behind the AI, both rolling forward.
  p.pos.x = a.model.root.position.x - fx * 7;
  p.pos.z = a.model.root.position.z - fz * 7;
  p.yaw = yaw;
  p.vel.x = fx * 45; p.vel.z = fz * 45;
  p.vLong = 45; p.vLat = 0;
  a.speed = 26;
  window.__apex.setDemoInput({ gas: true, brake: false, left: false, right: false, handbrake: false });

  const samples = [];
  const start = { x: p.pos.x, z: p.pos.z };
  const t0 = performance.now();
  await new Promise((resolve) => {
    function step() {
      const dx = p.pos.x - start.x, dz = p.pos.z - start.z;
      samples.push({
        t: (performance.now() - t0) / 1000,
        vLong: p.vLong,
        adv: dx * fx + dz * fz,
        side: dx * Math.cos(yaw) - dz * Math.sin(yaw),
        gap: Math.hypot(p.pos.x - a.model.root.position.x, p.pos.z - a.model.root.position.z)
      });
      if (performance.now() - t0 < 1600) requestAnimationFrame(step);
      else resolve();
    }
    requestAnimationFrame(step);
  });

  const minVLong = Math.min(...samples.map((s) => s.vLong));
  const maxBack = Math.min(...samples.map((s) => s.adv));
  const minGap = Math.min(...samples.map((s) => s.gap));
  const end = samples[samples.length - 1];
  return {
    frames: samples.length,
    minVLong: +minVLong.toFixed(2),
    maxBackwardTravel: +maxBack.toFixed(2),
    minCentreGap: +minGap.toFixed(2),
    endVLong: +end.vLong.toFixed(2),
    endAdvance: +end.adv.toFixed(2),
    endSide: +end.side.toFixed(2)
  };
});

console.log(JSON.stringify(result, null, 2));
await page.screenshot({ path: '/tmp/opencode/collision-contact.jpg', type: 'jpeg', quality: 70 });
await browser.close();

