import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR
  || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
const systemChrome = process.env.CHROME_PATH || '/opt/google/chrome/chrome';
if (systemChrome) launchOptions.executablePath = systemChrome;
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 1100, height: 660 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:3011/?demo=race&go=1&input=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.race && window.__apex.race.state === 'racing', null, { timeout: 60000 });
// let it race for a while with steering input
await page.waitForTimeout(12000);
const state = await page.evaluate(() => {
  const r = window.__apex.race;
  return {
    state: r.state,
    time: Math.round(r.time),
    kmh: Math.round(Math.abs(r.player.vLong) * 3.6),
    vLong: +r.player.vLong.toFixed(1),
    vLat: +r.player.vLat.toFixed(1),
    lap: r.player.lapsCompleted + 1,
    trackDist: +r.player.trackDist.toFixed(1),
    aiGaps: r.ai.map((a) => +Math.hypot(a.model.root.position.x - r.player.pos.x, a.model.root.position.z - r.player.pos.z).toFixed(1))
  };
});
console.log(JSON.stringify(state));
console.log('errors:', errors.length ? errors.slice(0, 5) : 'none');
await page.screenshot({ path: '/tmp/opencode/race-live.jpg', type: 'jpeg', quality: 70 });
await browser.close();

