import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR
  || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
const systemChrome = process.env.CHROME_PATH || '/opt/google/chrome/chrome';
if (systemChrome) launchOptions.executablePath = systemChrome;
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 1000, height: 620 } });
page.on('pageerror', (e) => console.log('PAGE ERROR:', e.message));
await page.goto('http://127.0.0.1:3011/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.race && window.__apex.race.state === 'racing', null, { timeout: 60000 });

const info = await page.evaluate(async () => {
  const r = window.__apex.race;
  const p = r.player;
  const a = r.ai[0];
  r.ai[1].dist = -600;
  r.ai[2].dist = -640;
  const yaw = a.model.root.rotation.y;
  const fx = Math.sin(yaw), fz = Math.cos(yaw);
  // Turn this into a straight-line side-by-side pass: player half a car
  // width to the inside, closing on a car that holds 27 m/s.
  p.pos.x = a.model.root.position.x - fx * 6 + Math.cos(yaw) * 1.6;
  p.pos.z = a.model.root.position.z - fz * 6 - Math.sin(yaw) * 1.6;
  p.yaw = yaw;
  p.vel.x = fx * 42; p.vel.z = fz * 42;
  p.vLong = 42; p.vLat = 0;
  window.__apex.setDemoInput({ gas: true, brake: false, left: false, right: true, handbrake: false });

  const samples = [];
  const t0 = performance.now();
  await new Promise((resolve) => {
    function step() {
      a.speed = 27;
      const gap = Math.hypot(p.pos.x - a.model.root.position.x, p.pos.z - a.model.root.position.z);
      samples.push({ gap: +gap.toFixed(2), vLong: +p.vLong.toFixed(1), aiLat: +a.lateral.toFixed(2), rel: +(gap - 3.2).toFixed(2) });
      if (performance.now() - t0 < 5000) requestAnimationFrame(step);
      else resolve();
    }
    requestAnimationFrame(step);
  });
  return {
    minVLong: Math.min(...samples.map((s) => s.vLong)),
    minGap: Math.min(...samples.map((s) => s.gap)),
    maxAiLat: Math.max(...samples.map((s) => Math.abs(s.aiLat))),
    contactFrames: samples.filter((s) => s.gap < 4.6).length,
    tail: samples.slice(-10)
  };
});
console.log(JSON.stringify(info, null, 1));
await browser.close();

